-- Add three additional questions to each existing Python Foundations lesson.
-- The last question in each set applies or traces the lesson concept.
WITH bank(week_no, session_no, questions, correct_options, explanations) AS (
  VALUES
  (1,1, $$[{"question":"What does print(student_name) show after student_name = \"Sam\"?","options":["Sam","student_name","Nothing"]},{"question":"Which line stores a value instead of displaying it?","options":["print(\"Hi\")","room = \"Blue Room\"","# welcome"]},{"question":"What will this display, in order? room = \"Blue Room\"; print(room); print(\"Ready\")","options":["Blue Room, then Ready","room, then Ready","Only Ready"]}]$$::jsonb, ARRAY[0,1,0]::smallint[], ARRAY['print reads and displays the value stored in student_name.','Assignment stores a value under a variable name; print displays it.','The first print displays the saved room value, then the next print displays Ready.']),
  (1,2, $$[{"question":"If someone types two spaces before and after Amina, what does name.strip() remove?","options":["Spaces at the beginning and end","Every space, including spaces between words","The letters in the name"]},{"question":"Which line inserts name into a greeting message?","options":["print(\"Hello, name!\")","print(f\"Hello, {name}!\")","print(name = \"Hello\")"]},{"question":"After typing Amina, what does this display? name = input(...).strip(); print(f\"Hi, {name}!\")","options":["Hi, Amina!","Hi, {name}!","Name? Amina"]}]$$::jsonb, ARRAY[0,1,0]::smallint[], ARRAY['strip removes whitespace only from the two ends of the text.','An f-string uses braces to insert the current value of a variable.','The input answer is cleaned, then inserted between Hi and the exclamation mark.']),
  (1,3, $$[{"question":"What happens if int() receives the text twelve?","options":["It cannot convert the word to an integer","It guesses the number 12","It prints the word twice"]},{"question":"Which value can int(\"12\") produce?","options":["The number 12","The text \"12\"","The decimal 1.2"]},{"question":"A learner types 8 and the program runs int(input(...)) + 3. What is the result?","options":["11","83","An error because input is always text"]}]$$::jsonb, ARRAY[0,0,0]::smallint[], ARRAY['int can convert digit text such as 12, but the word twelve is not a valid integer spelling.','int converts the digit text into the whole number 12.','The conversion makes 8 a number, so arithmetic gives 11.']),
  (1,4, $$[{"question":"In def welcome(name):, what is name?","options":["A parameter that receives a value","The argument from every future call","A Python keyword"]},{"question":"Why indent the print line under def?","options":["It marks the line as part of the function body","It makes the line a comment","It runs the function immediately"]},{"question":"What does this display? def welcome(name): print(f\"Hi, {name}\"); welcome(\"Mina\")","options":["Hi, Mina","Hi, name","Nothing, because def calls the function"]}]$$::jsonb, ARRAY[0,0,0]::smallint[], ARRAY['The parameter is the named slot filled when the function is called.','Indentation groups the function instructions into its body.','The call supplies Mina as the argument, so name holds Mina during this run.']),
  (1,5, $$[{"question":"What is the difference between print(total) and return total inside a function?","options":["print displays the value; return sends it back to the caller","They always do the same thing","return displays the value twice"]},{"question":"Which line lets another part of the program save a function result?","options":["return count + 1","print(count + 1)","input(count + 1)"]},{"question":"What is stored in answer? def add(a, b): return a + b; answer = add(4, 3)","options":["7","None, because return cannot be saved","The text \"4 + 3\""]}]$$::jsonb, ARRAY[0,0,0]::smallint[], ARRAY['return gives a value to the calling code; print only shows it to a person.','A returned expression can be assigned by the line that called the function.','The function returns the sum 7, and the assignment stores that value in answer.']),

  (2,1, $$[{"question":"What is the difference between score = 10 and score == 10?","options":["= stores a value; == compares values","They both compare values","== stores a value; = compares values"]},{"question":"What does an if condition produce?","options":["True or False","A printed sentence every time","A new variable automatically"]},{"question":"If temperature is 29, which branch runs? if temperature > 25: print(\"Warm\") else: print(\"Cool\")","options":["Warm","Cool","Both"]}]$$::jsonb, ARRAY[0,0,0]::smallint[], ARRAY['A single equals sign assigns a value, while two equals signs ask whether values match.','Python evaluates the condition as a Boolean value: True or False.','29 is greater than 25, so the if condition is true and Warm is printed.']),
  (2,2, $$[{"question":"If the if condition is true, does Python also run the later elif branch?","options":["No, it runs only the first matching branch","Yes, every branch runs","Only if else is missing"]},{"question":"Why put a specific rule before a broad rule?","options":["A broad true rule could match too early","Python reads rules from bottom to top","Specific rules need no conditions"]},{"question":"A score is 95. What should this ordered grade chain do? if score >= 90: A; elif score >= 80: B; else: C","options":["Choose A and skip the remaining branches","Choose both A and B","Choose C because it is last"]}]$$::jsonb, ARRAY[0,0,0]::smallint[], ARRAY['An if/elif/else chain runs the first branch whose condition is true.','Putting a broad match first can prevent later, more specific cases from being checked.','95 meets the first condition, so A runs and Python skips the rest of the chain.']),
  (2,3, $$[{"question":"When is adult and has_ticket True?","options":["Only when both conditions are True","When at least one is True","Only when both are False"]},{"question":"What does not has_ticket do?","options":["Reverses the True/False value","Checks whether a ticket is a number","Always becomes True"]},{"question":"For age >= 13 and has_ticket, age is 14 but has_ticket is False. What is the result?","options":["False","True","Python cannot combine these conditions"]}]$$::jsonb, ARRAY[0,0,0]::smallint[], ARRAY['and requires both conditions to be true.','not reverses a Boolean result.','The age condition is true, but the ticket condition is false; and requires both.']),
  (2,4, $$[{"question":"Does strip() remove spaces between words?","options":["No, it removes whitespace only at the ends","Yes, it removes every space","Only when the text is lowercase"]},{"question":"After answer.strip().lower(), which method runs first?","options":["strip()","lower()","They run at the same time"]},{"question":"What is the result of \"  HELLO  \".strip().lower()?","options":["hello"," HELLO ","HELLO"]}]$$::jsonb, ARRAY[0,0,0]::smallint[], ARRAY['strip removes outside whitespace and leaves spaces between words untouched.','Python evaluates the leftmost method first, then applies lower to its result.','strip removes the outside spaces; lower changes the letters to lowercase.']),
  (2,5, $$[{"question":"Does lower() change a file into a different file type?","options":["No, it changes the text used by the program","Yes, it converts the file contents","It removes the file extension"]},{"question":"What does endswith(\".pdf\") check?","options":["Whether the text ends with .pdf","Whether the file exists","Whether the file contains a PDF document"]},{"question":"Why clean case before checking REPORT.PDF with endswith(\".pdf\")?","options":["Lowercasing makes the ending comparable as .pdf","It changes the actual filename on disk","It proves the file is safe"]}]$$::jsonb, ARRAY[0,0,0]::smallint[], ARRAY['lower changes the string value being checked, not an external file.','endswith checks the ending characters of a string.','Without lowercasing, uppercase .PDF would not match lowercase .pdf.']),
  (2,6, $$[{"question":"How many minutes are in one hour?","options":["60","30","100"]},{"question":"How do you convert minutes to part of an hour?","options":["Divide minutes by 60","Multiply minutes by 60","Add 60 to the minutes"]},{"question":"A time is 7:30. What decimal hour does 7 + 30 / 60 represent?","options":["7.5","7.3","37"]}]$$::jsonb, ARRAY[0,0,0]::smallint[], ARRAY['One hour contains 60 minutes.','Dividing the minute count by 60 converts it into a fraction of an hour.','30 divided by 60 is 0.5, so 7 plus 0.5 equals 7.5.']),

  (3,1, $$[{"question":"What change usually helps a while loop eventually stop?","options":["Update a value used in its condition","Repeat the same unchanged value forever","Remove every indented line"]},{"question":"When does Python check a while condition?","options":["Before each repetition","Only after the program ends","Only the first time"]},{"question":"How many times does this loop print? count = 0; while count < 3: print(count); count += 1","options":["Three times","Two times","Forever"]}]$$::jsonb, ARRAY[0,0,0]::smallint[], ARRAY['Changing the condition value lets the loop reach a stopping point.','Python checks the condition before each run of the loop body.','It prints 0, 1, and 2; then count is 3 and the condition is false.']),
  (3,2, $$[{"question":"In for name in names, what does name hold during each pass?","options":["The current item from names","Always the list length","The whole list every time"]},{"question":"What numbers does range(3) produce?","options":["0, 1, and 2","1, 2, and 3","0, 1, 2, and 3"]},{"question":"What is printed by for name in [\"Mina\", \"Ali\"]: print(name)?","options":["Mina, then Ali","Only Mina","The list indexes 0 and 1"]}]$$::jsonb, ARRAY[0,0,0]::smallint[], ARRAY['The loop variable is assigned each item as the loop visits it.','range starts at zero and stops before its endpoint.','The loop visits both list values in order, printing each once.']),
  (3,3, $$[{"question":"If supplies has three items, what does len(supplies) return?","options":["3","2, because indexes start at zero","The first item"]},{"question":"What does supplies[1] select?","options":["The second item","The first item","The number of items"]},{"question":"What does this display? items = [\"pen\", \"book\"]; print(items[0]); print(len(items))","options":["pen, then 2","book, then 1","0, then pen"]}]$$::jsonb, ARRAY[0,0,0]::smallint[], ARRAY['len counts items; it does not report the last index.','Index 0 is first, so index 1 is second.','The first line displays the item at index zero; len reports two items.']),
  (3,4, $$[{"question":"What does append(value) add to a list?","options":["One item at the end","Every character of the value","An item at index zero only"]},{"question":"What does remove(value) remove?","options":["The first matching value","The last item always","Every item in the list"]},{"question":"After items = [\"pen\", \"book\"]; removed = items.pop(), what are items and removed?","options":["items is [\"pen\"]; removed is \"book\"","items is unchanged; removed is None","items is [\"book\"]; removed is \"pen\""]}]$$::jsonb, ARRAY[0,0,0]::smallint[], ARRAY['append adds one supplied item to the end of the list.','remove searches from the beginning and removes the first equal value.','pop with no index removes and returns the final list item.']),
  (3,5, $$[{"question":"What does replace(old, new) return?","options":["A new string with matching text replaced","The original string changed in place","A list of every letter"]},{"question":"What does strip() remove from \"  hi  \"?","options":["Whitespace at the two ends","The letters h and i","Spaces between all words"]},{"question":"After message = \"Welcome Mina\"; cleaned = message.replace(\"Welcome\", \"Hello\"), what are message and cleaned?","options":["message stays Welcome Mina; cleaned is Hello Mina","Both become Hello Mina","message becomes empty; cleaned is Mina"]}]$$::jsonb, ARRAY[0,0,0]::smallint[], ARRAY['String methods return changed text; they do not edit the original string in place.','strip removes whitespace at the start and end only.','The returned replacement is assigned to cleaned; message retains its original value.']),
  (3,6, $$[{"question":"In text[1:4], which positions are included?","options":["1, 2, and 3; position 4 is excluded","0, 1, 2, 3, and 4","Only position 4"]},{"question":"What is the index of the first character in a string?","options":["0","1","The string length"]},{"question":"What does \"PYTHON\"[1:4] return, and why?","options":["YTH; it starts at 1 and stops before 4","YTHO; both endpoints are included","Pyth; indexes start at 1"]}]$$::jsonb, ARRAY[0,0,0]::smallint[], ARRAY['A slice includes its start index and stops before its end index.','Python indexes begin at zero.','Positions 1, 2, and 3 contain Y, T, and H.']),
  (3,7, $$[{"question":"What kind of value can a dictionary key help you look up?","options":["Its related value","The list length only","A random item"]},{"question":"What is useful about scores.get(\"Mina\", 0) if Mina is missing?","options":["It returns the fallback 0","It always raises KeyError","It adds Mina automatically"]},{"question":"A dictionary is scores = {\"Mina\": 8}. What does scores.get(\"Ali\", 0) return?","options":["0","8","\"Ali\""]}]$$::jsonb, ARRAY[0,0,0]::smallint[], ARRAY['A dictionary maps a key to its associated value.','get can return a default instead of raising an error for a missing key.','Ali is not a key, so get returns the supplied default value, zero.']),
  (3,8, $$[{"question":"Which collection is a better fit when the group should stay fixed?","options":["A tuple","A list","A string method"]},{"question":"Which bracket style creates a tuple with two values?","options":["(1, 2)","[1, 2]","{1: 2}"]},{"question":"Why choose a tuple for the days Mon and Tue when they should not be edited?","options":["A tuple represents a fixed group","A tuple automatically sorts values","Tuples store only numbers"]}]$$::jsonb, ARRAY[0,0,0]::smallint[], ARRAY['Tuples are useful for a fixed collection of related values.','Parentheses and commas create a tuple.','The fixed pair suits a tuple better than a changeable list.']),
  (3,9, $$[{"question":"Which parts does a list comprehension combine?","options":["An output expression and a loop","A class and an object","A file and a folder"]},{"question":"In [name.title() for name in names], what happens for each name?","options":["Its title-cased form is added to a new list","The original list is deleted","Only names beginning with T are kept"]},{"question":"If names is [\"mina\", \"ali\"], what does [name.title() for name in names] produce?","options":["[\"Mina\", \"Ali\"]","[\"mina\", \"ali\"]","[\"M\", \"A\"]"]}]$$::jsonb, ARRAY[0,0,0]::smallint[], ARRAY['A comprehension creates a list by evaluating an expression for each item.','The expression name.title() is evaluated once for each name.','title() capitalizes the start of each word, producing the two formatted names.']),

  (4,1, $$[{"question":"What does a SyntaxError usually mean?","options":["Python could not read the code structure","A variable has the wrong value after running","The program calculated the wrong answer"]},{"question":"Which error can int(\"cat\") raise?","options":["ValueError","SyntaxError","NameError"]},{"question":"The code runs but gives the wrong total. Which error type best fits?","options":["A logic error","A syntax error","An import error"]}]$$::jsonb, ARRAY[0,0,0]::smallint[], ARRAY['A syntax error means Python could not parse the written instructions.','The code is valid Python, but the text cannot be converted to an integer, causing ValueError.','When code runs but produces the wrong result, inspect the program logic.']),
  (4,2, $$[{"question":"Which code belongs in a try block?","options":["The operation that might fail","The explanation for every possible bug","Only a comment"]},{"question":"What does except ValueError do?","options":["Handles a matching conversion error","Runs only when conversion succeeds","Repeats input automatically"]},{"question":"A user types four for int(input()). Which flow is appropriate?","options":["Conversion raises ValueError and the matching except responds","The else block runs because four is a word","Python converts it to 4 automatically"]}]$$::jsonb, ARRAY[0,0,0]::smallint[], ARRAY['Put the risky operation inside try so a matching error can be handled.','except handles the named error type if that error occurs.','The text four is not an integer spelling, so int raises ValueError and except handles it.']),
  (4,3, $$[{"question":"Why ask again inside a validation loop?","options":["An invalid answer can be replaced with a new attempt","Python changes the first answer automatically","A loop removes the need for a condition"]},{"question":"What does break do inside a loop?","options":["Leaves the loop","Restarts the whole program","Skips every later function"]},{"question":"A valid number is entered in a while True loop. What must the code do to stop asking?","options":["Run break after confirming it is valid","Print the answer and keep looping","Catch ValueError even though conversion worked"]}]$$::jsonb, ARRAY[0,0,0]::smallint[], ARRAY['Repeating the prompt gives the learner another chance after invalid input.','break exits the nearest loop.','After validation succeeds, break exits the intentional infinite loop.']),
  (4,4, $$[{"question":"What should a function do before dividing by a value that might be zero?","options":["Check the denominator and handle zero clearly","Convert zero to text","Ignore the denominator"]},{"question":"What does raise ValueError(\"amount must be positive\") do?","options":["Stops with a clear error for an invalid value","Prints a warning and continues normally","Changes amount to a positive number"]},{"question":"A percentage function receives total=0. Why handle this before dividing?","options":["Division by zero is undefined and raises an error","Zero is not an integer","Python treats zero as one"]}]$$::jsonb, ARRAY[0,0,0]::smallint[], ARRAY['Checking the denominator prevents an expected invalid case from causing an unclear crash.','raise signals that the caller supplied an invalid value; it does not change the value.','Dividing by zero raises ZeroDivisionError, so the function needs a clear policy for this case.']),
  (4,5, $$[{"question":"What is a useful way to narrow down a bug?","options":["Reproduce it, then inspect a small relevant part","Change many unrelated lines at once","Ignore the input that caused it"]},{"question":"What does a traceback help you find?","options":["Where an error occurred and what type it was","The intended design of the whole program","The user password"]},{"question":"A program gives a wrong total only when quantity is 0. What is the best next step?","options":["Repeat that case and inspect the boundary calculation","Rewrite the whole program without checking","Assume print() changed the quantity"]}]$$::jsonb, ARRAY[0,0,0]::smallint[], ARRAY['A repeatable example makes it easier to locate the source of the problem.','A traceback reports the error and the path of calls or lines leading to it.','The zero case is a boundary; reproduce it and inspect the relevant logic.']),

  (5,1, $$[{"question":"What does import random make available?","options":["The random module and its tools","A random value in every variable","A list named random"]},{"question":"After import random, how can you call choice?","options":["random.choice(items)","choice.random(items)","items.random.choice"]},{"question":"A program uses random.choice([\"read\", \"draw\"]). What does it return?","options":["One item selected from the list","Both items every time","The list length"]}]$$::jsonb, ARRAY[0,0,0]::smallint[], ARRAY['Importing a module makes its named tools available.','The module name comes before the dot and function name.','choice selects and returns one item from the supplied sequence.']),
  (5,2, $$[{"question":"Can randint(1, 6) return 1?","options":["Yes, both endpoints are included","No, it only returns 2 through 5","Only on the second call"]},{"question":"What is a sensible use for random.choice?","options":["Pick one activity from a list","Convert text to an integer","Read a file row"]},{"question":"A dice simulation uses random.randint(1, 6). Which outcome is possible?","options":["6","0 only","7"]}]$$::jsonb, ARRAY[0,0,0]::smallint[], ARRAY['randint includes both its starting and ending values.','choice returns one of the supplied items.','Because both endpoints are included, 6 is a possible result.']),
  (5,3, $$[{"question":"Is python -m pip install emoji Python code for the editor?","options":["No, it is a terminal command","Yes, it is a print statement","Yes, it creates a variable"]},{"question":"What is an outside package?","options":["An additional tool installed into a Python environment","A built-in Python keyword","A folder name in every program"]},{"question":"Why may import emoji fail in a fresh environment?","options":["The package might not be installed there yet","Imports only work inside print","Python cannot use external tools"]}]$$::jsonb, ARRAY[0,0,0]::smallint[], ARRAY['pip install commands belong in the system terminal.','Outside packages add tools that are not part of the standard library.','A program can import a package only when it is installed in its environment.']),
  (5,4, $$[{"question":"What is stored at sys.argv[0] in a typical Python run?","options":["The program filename","The first user-supplied argument","The last argument"]},{"question":"What does sys.argv contain?","options":["Command-line arguments as text","Only whole numbers","The program output"]},{"question":"A command is python greet.py Mina. What is usually sys.argv[1]?","options":["Mina","greet.py","python"]}]$$::jsonb, ARRAY[0,0,0]::smallint[], ARRAY['Index zero contains the script name; supplied values follow it.','sys.argv is a list of command-line text values.','The script name is at index zero, making Mina the first user argument.']),
  (5,5, $$[{"question":"What can a JSON response from an API contain?","options":["Structured values such as objects, lists, text, and numbers","Only a Python function","Only an image"]},{"question":"Why might a price be converted with float()?","options":["To use decimal digits in arithmetic","To turn it into a file","To send it back to the API"]},{"question":"An API returns the text 12.50. What lets the program calculate with it as a decimal?","options":["float(\"12.50\")","print(\"12.50\")","str(\"12.50\")"]}]$$::jsonb, ARRAY[0,0,0]::smallint[], ARRAY['JSON represents structured data an API can return.','A number stored as text must be converted before numeric arithmetic.','float converts decimal digit text into a value usable in calculations.']),
  (5,6, $$[{"question":"Why prefer chosen_activity over x for a saved activity?","options":["The name explains what the value represents","Long names make Python run faster","Python requires descriptive names"]},{"question":"Which comment is most useful?","options":["One explaining why a non-obvious step is needed","One repeating every line word for word","A comment containing random letters"]},{"question":"A teammate opens your program next month. What helps them understand a variable fastest?","options":["A clear name such as total_cost","A short name such as q for everything","Removing all spaces"]}]$$::jsonb, ARRAY[0,0,0]::smallint[], ARRAY['A descriptive name communicates the role of the value.','Comments are most useful when they explain purpose or a non-obvious decision.','A meaningful name preserves context for someone reading the code later.']),

  (6,1, $$[{"question":"Why protect interactive startup with a main guard?","options":["Importing the file can expose functions without running prompts","It makes all tests pass automatically","It converts input into a number"]},{"question":"What is __name__ when a file is run directly?","options":["__main__","The filename plus .py","None"]},{"question":"A test imports a module with a main guard. What should happen?","options":["Functions load; main() does not start","The input prompt must always run","Python skips every function"]}]$$::jsonb, ARRAY[0,0,0]::smallint[], ARRAY['The guard keeps prompts from starting only because a test imports the module.','Python sets __name__ to __main__ for a file it runs directly.','During import, __name__ is the module name, so the guarded call is skipped.']),
  (6,2, $$[{"question":"What does a passing assert communicate?","options":["The tested condition is True","The program has no bugs","The function returns text"]},{"question":"What error does a failed assert raise?","options":["AssertionError","ValueError","ImportError"]},{"question":"If assert square(3) == 9 fails, what should you investigate?","options":["Whether square(3) returns the expected value","Whether Python can print 9","Whether assert changed the function"]}]$$::jsonb, ARRAY[0,0,0]::smallint[], ARRAY['assert checks whether a condition is true.','A false assertion raises AssertionError.','The failure means the actual result differs from the expectation.']),
  (6,3, $$[{"question":"What is a boundary test?","options":["A test near an important limit such as zero","A test that skips the function","A test of the program title"]},{"question":"Should invalid inputs be tested?","options":["Yes, to check they are handled clearly","No, only ordinary values matter","Only if they are positive"]},{"question":"A function accepts ages 0 through 120. Which is a useful boundary test?","options":["Test 0 and 120, plus values just outside","Test only 50","Test a word in the function name"]}]$$::jsonb, ARRAY[0,0,0]::smallint[], ARRAY['Boundary tests check values at or near the edges of valid input.','Testing invalid values checks that the program responds safely and clearly.','The endpoints and nearby invalid values reveal off-by-one and validation errors.']),
  (6,4, $$[{"question":"What name helps pytest discover a test function?","options":["A name beginning with test_","A name ending with _run","Any name containing a dash"]},{"question":"What does pytest do with a failed assertion?","options":["Reports the test and failed comparison","Fixes the expected value","Deletes the tested function"]},{"question":"Why name tests test_...?","options":["pytest can discover and run them","Python only allows functions with that prefix","The prefix changes the test result"]}]$$::jsonb, ARRAY[0,0,0]::smallint[], ARRAY['pytest discovers test functions using the test_ naming convention by default.','A failed assertion is reported so the developer can inspect the failure.','The naming convention lets pytest find the test function automatically.']),
  (6,5, $$[{"question":"What should an import do when a module has a main guard?","options":["Make functions available without starting the prompt","Always run main()","Delete the module variables"]},{"question":"When does a guarded main() call run?","options":["When the file is run directly","Whenever a test imports it","Only after pytest ends"]},{"question":"A test imports greet from a file with a guarded prompt. What can it do?","options":["Call greet with a test value without opening the prompt","It must answer the prompt first","It cannot import functions"]}]$$::jsonb, ARRAY[0,0,0]::smallint[], ARRAY['The guard separates reusable definitions from interactive startup.','The comparison is true only when Python runs this file as the main program.','Importing exposes greet while skipping the guarded interactive main call.']),

  (7,1, $$[{"question":"What does file.read() return in text mode?","options":["The file contents as text","A list of file names","The file size only"]},{"question":"What does with open(...) do when its block finishes?","options":["Closes the file safely","Deletes the file","Prints every line automatically"]},{"question":"Why can open(names.txt) fail in the browser editor?","options":["The file may not exist in the editor environment","Python cannot read text files","The filename must be a variable"]}]$$::jsonb, ARRAY[0,0,0]::smallint[], ARRAY['read returns the opened file contents as a string.','with manages the file and closes it after the block.','Browser practice may not have access to files on the learner computer.']),
  (7,2, $$[{"question":"What can write mode w do to an existing file?","options":["Replace its old contents","Only add to the end","Read without changing it"]},{"question":"Does file.write(text) automatically add a newline?","options":["No","Yes, after every call","Only for CSV files"]},{"question":"You need to keep old notes and add a line. Which mode is suitable?","options":["Append mode a","Write mode w","Read mode r"]}]$$::jsonb, ARRAY[0,0,0]::smallint[], ARRAY['Write mode creates or replaces file contents.','write adds exactly the supplied text, so include a newline when needed.','Append preserves earlier contents and adds new text at the end.']),
  (7,3, $$[{"question":"What does DictReader use as dictionary keys for a CSV row?","options":["The column headings","The row numbers","The file extension"]},{"question":"How can you access a student name from a DictReader row?","options":["row[\"name\"]","row.name()","row[0].name"]},{"question":"If the CSV header is name,score, what does row[\"score\"] refer to?","options":["The score field in the current row","The second file","The header text only"]}]$$::jsonb, ARRAY[0,0,0]::smallint[], ARRAY['DictReader maps each row value to its header name.','Dictionary-style lookup uses the header string as a key.','score selects that field from the row currently being processed.']),
  (7,4, $$[{"question":"Why keep the source CSV unchanged during a conversion?","options":["It protects the original if the new output has a mistake","Python can only read a file once","The output must always be empty"]},{"question":"What should DictWriter.writeheader() write?","options":["The column names","Every data row twice","The program source code"]},{"question":"A conversion reorders names. Which approach is safer?","options":["Read the source and write results to a separate output file","Overwrite the source before checking the result","Delete the headings"]}]$$::jsonb, ARRAY[0,0,0]::smallint[], ARRAY['A separate output protects the original data.','writeheader writes the CSV field names as the first row.','A separate output lets you inspect transformed data and retain the source.']),
  (7,5, $$[{"question":"Where should python -m pip install pillow be entered?","options":["A system terminal","Inside a Python string","As a filename extension"]},{"question":"What does Image.open(photo.png) need?","options":["An image file available to that Python environment","A CSV header","A function named photo"]},{"question":"Why might a Pillow program work locally but not in the browser editor?","options":["The browser environment may lack Pillow or the image file","Pillow works only with text","The import command belongs inside print"]}]$$::jsonb, ARRAY[0,0,0]::smallint[], ARRAY['Installation commands run in the operating system terminal.','The program can open only an image file it can access.','Browser environments may not include the package or local image files.']),

