  (10,5, $$[{"question":"What is the base case in recursion?","options":["The condition that stops further calls","The first function name","A print statement that runs forever"]},{"question":"What should each recursive call usually do?","options":["Move toward a smaller problem or the base case","Repeat the exact same input forever","Delete the function"]},{"question":"For countdown(3), which sequence reaches the base case at zero?","options":["3, 2, 1, then 0 stops","3 forever","0, 3, 2, then repeat"]}]$$::jsonb, ARRAY[0,0,0]::smallint[], ARRAY['A base case tells the function when to stop calling itself.','Progress toward a base case prevents endless recursive calls.','Each call subtracts one, eventually reaching zero where recursion stops.'])
), rotated AS (
  SELECT b.week_no,b.session_no,b.explanations,
         jsonb_agg(jsonb_set(question.value,'{options}',jsonb_build_array(
           question.value->'options'->rotation.shift_by,
           question.value->'options'->((rotation.shift_by+1)%3),
           question.value->'options'->((rotation.shift_by+2)%3)
         )) ORDER BY question.ordinal) AS questions,
         array_agg(((b.correct_options[question.ordinal::integer]-rotation.shift_by+3)%3)::smallint ORDER BY question.ordinal) AS correct_options
  FROM bank b
  CROSS JOIN LATERAL jsonb_array_elements(b.questions) WITH ORDINALITY AS question(value,ordinal)
  CROSS JOIN LATERAL (SELECT ((b.week_no+b.session_no+question.ordinal::integer)%3) AS shift_by) AS rotation
  GROUP BY b.week_no,b.session_no,b.explanations
), targets AS (
  SELECT m.order_index AS week_no, s.session_number, s.id AS session_id, s.quick_check AS old_check,
         r.questions, r.correct_options, r.explanations
  FROM public.courses c JOIN public.modules m ON m.course_id=c.id
  JOIN public.sessions s ON s.module_id=m.id
  JOIN rotated r ON r.week_no=m.order_index AND r.session_no=s.session_number
  WHERE c.slug='python-foundations'
)
UPDATE public.sessions s
SET quick_check=jsonb_set(t.old_check,'{questions}',
  jsonb_build_array(jsonb_build_object('question',t.old_check->>'question','options',t.old_check->'options')) || t.questions,true)
FROM targets t WHERE s.id=t.session_id;

